import { readFile } from "node:fs/promises";

import { drizzle } from "drizzle-orm/node-postgres";
import { Client } from "pg";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { schema } from "@/lib/db/schema";

const databaseUrl = process.env.DATABASE_URL;

if (databaseUrl) {
  describe("sighting persistence", () => {
    let client: Client;

    beforeEach(async () => {
      client = new Client({ connectionString: databaseUrl });
      await client.connect();
      await client.query('DROP TABLE IF EXISTS "sightings"');

      const migration = await readFile(
        new URL(
          "../../drizzle/20260811072733_early_luke_cage/migration.sql",
          import.meta.url
        ),
        "utf8"
      );
      for (const statement of migration.split("--> statement-breakpoint")) {
        await client.query(statement);
      }
    });

    afterEach(async () => {
      await client.end();
    });

    it("applies the baseline constraints and permits duplicate label facts", async () => {
      const database = drizzle(databaseUrl, { schema });
      const { createSightingOperations } = await import("./sightings.server");
      const operations = createSightingOperations(database);

      try {
        const first = await operations.create({
          labelDate: "2026-08-11",
          labelMinute: 845,
        });
        const duplicate = await operations.create({
          labelDate: "2026-08-11",
          labelMinute: 845,
        });

        expect(first).toMatchObject({
          ok: true,
          sighting: {
            doneness: null,
            labelDate: "2026-08-11",
            labelMinute: 845,
          },
        });
        expect(duplicate).toMatchObject({
          ok: true,
          sighting: { labelDate: "2026-08-11", labelMinute: 845 },
        });
        expect(
          first.ok && duplicate.ok && duplicate.sighting.id
        ).toBeGreaterThan(first.ok ? first.sighting.id : 0);

        await expect(
          client.query(
            "insert into sightings (label_date, label_minute) values ('2026-08-11', 1440)"
          )
        ).rejects.toMatchObject({ code: "23514" });
        await expect(
          client.query(
            "insert into sightings (label_date, label_minute, doneness) values ('2026-08-11', 0, 'raw')"
          )
        ).rejects.toMatchObject({ code: "23514" });
      } finally {
        await database.$client.end();
      }
    });

    it("creates the required representation and only its initial recency index", async () => {
      const columns = await client.query<{ column_name: string }>(
        "select column_name from information_schema.columns where table_name = 'sightings' order by ordinal_position"
      );
      const indexes = await client.query<{ indexname: string }>(
        "select indexname from pg_indexes where tablename = 'sightings' order by indexname"
      );

      expect(columns.rows.map((column) => column.column_name)).toEqual([
        "id",
        "label_date",
        "label_minute",
        "doneness",
        "created_at",
        "updated_at",
      ]);
      expect(indexes.rows.map((index) => index.indexname)).toEqual([
        "sightings_pkey",
        "sightings_recent_idx",
      ]);
    });
  });
}
### docs/feature/phase-01/014-capture-durable-label-time/plan.md
# 014 — Capture and Durably Save Label Time

## Source

GitHub issue [#14](https://github.com/chris-tse/costco-chicken-tracker/issues/14),
the durable Capture checkpoint from [#12](https://github.com/chris-tse/costco-chicken-tracker/issues/12).

## Scope

1. Introduce the fresh `sightings` schema and a baseline PostgreSQL migration.
2. Expose one validated, explicit create operation that returns the complete durable sighting.
3. Replace the shell with mobile-first Capture, defaulted from the device clock, with literal
   label-date/minute entry, non-blocking store-hours warning, validation, progress, success,
   and recoverable persistence failure states.

## Test seams

- Capture route behavior, observed through React Testing Library with a controlled clock and
  injected save operation.
- The explicit sighting-create operation, observed against disposable real PostgreSQL after
  applying the committed baseline migration.

## Verification

Run lint, typecheck, all Vitest suites (including the PostgreSQL integration suite in CI), and
the production build.
### docs/feature/phase-01/014-capture-durable-label-time/research.md
# 014 — Capture and Durably Save Label Time Research

## 2026-08-11

- #14 establishes the fresh `sightings` persistence baseline deferred by #13. It intentionally
  has no user, location, timezone, offset, seconds, soft-delete, or concurrency-version data.
- Label date and label minute are literal facts. The UI gets defaults from the browser device
  clock; persistence stores the date text and minute-after-midnight without conversion.
- The first success confirmation remains within Capture. The focused completion and optional
  doneness flow are the next checkpoint (#15), so this checkpoint does not add completion,
  correction, recency, navigation, or planner behavior.

